void format_selection_as_block_elements(const VisiblePosition& startOfSelection, const VisiblePosition& endOfSelection) {
    // Check if the start position is at an unsplittable element
    if (is_unsplittable_element(startOfSelection)) {
        create_block_element_with_placeholder(startOfSelection);
    }

    // Process paragraphs within the selection
    VisiblePosition position = startOfSelection;
    while (!position.is_equal(endOfSelection)) {
        if (is_paragraph_boundary(position)) {
            format_paragraph(position);
        }

        // Ensure the selection remains valid despite document changes
        if (has_document_mutated()) {
            revalidate_selection(startOfSelection, endOfSelection);
        }

        // Move to the next position
        position = position.next();
    }

    // Final sanity check before exit
    assert_selection_valid(startOfSelection, endOfSelection);
}

void format_text_selection(const VisiblePosition& startOfSelection, const VisiblePosition& endOfSelection) {
    if (is_unsplittable_element(startOfSelection)) {
        create_block_element(startOfSelection);
        create_placeholder(startOfSelection);
    }

    VisiblePosition currentPos = startOfSelection;

    while (!currentPos.is_after(endOfSelection)) {
        if (is_paragraph(currentPos)) {
            format_paragraph(currentPos);

            if (is_inside_table_cell(currentPos)) {
                restrict_formatting_to_table_cell(currentPos);
            }

            ensure_selection_validity(currentPos);
        }

        currentPos = move_to_next_position(currentPos);
    }

    perform_sanity_check();
}

void formatSelectionAsBlockElements(const VisiblePosition& startOfSelection, const VisiblePosition& endOfSelection) {
    // Check if the start is inside an unsplittable element
    if (isUnsplittableElement(startOfSelection.node)) {
        // Create a block element and a placeholder
        Node* block = createBlockElement();
        Node* placeholder = createPlaceholderElement();

        insertBefore(block, startOfSelection.node);
        insertAfter(placeholder, startOfSelection.node);
    }

    VisiblePosition current = startOfSelection;

    while (current != endOfSelection) {
        Node* currentNode = current.node;

        if (isParagraph(currentNode)) {
            formatParagraph(currentNode);
        } else if (isTableCell(currentNode)) {
            // Ensure formatting does not disrupt table structure
            formatTableCellContent(currentNode);
        }

        // Validate the selection remains valid
        if (!isSelectionValid(startOfSelection, endOfSelection)) {
            break;
        }

        current = nextVisiblePosition(current);
    }

    // Perform a final check to ensure the document structure remains intact
    validateDocumentStructure();
}

void formatSelectionAsBlock(const VisiblePosition& startOfSelection, const VisiblePosition& endOfSelection) {
    if (isAtUnsplittableElement(startOfSelection)) {
        createBlockElement(startOfSelection);
        insertPlaceholder(startOfSelection);
    }

    VisiblePosition current = startOfSelection;
    while (!current.isEqual(endOfSelection)) {
        if (isParagraph(current)) {
            formatParagraph(current);
            ensureTableStructureIntegrity(current);
        }
        current = current.next();
    }

    validateSelection(startOfSelection, endOfSelection);
    runDocumentMutationSanityChecks();
}

void formatSelectionAsBlockElement(const VisiblePosition& startOfSelection, const VisiblePosition& endOfSelection) {
    if (isUnsplittableElement(startOfSelection)) {
        createBlockElementAndPlaceholder(startOfSelection);
    }

    VisiblePosition currentPos = startOfSelection;
    while (currentPos != endOfSelection && !currentPos.isNull()) {
        if (isParagraphNode(currentPos)) {
            if (isInsideTableCell(currentPos)) {
                formatParagraphInsideTableCell(currentPos);
            } else {
                formatParagraph(currentPos);
            }
        }
        currentPos = nextVisiblePosition(currentPos);
    }

    ensureSelectionValidity(startOfSelection, endOfSelection);
}
